using Microsoft.Data.SqlClient;
using System.Data;
using System.Security.Claims;

public static class ManagementSuite
{
    static Guid UserId(ClaimsPrincipal u)=>Guid.Parse(u.FindFirstValue(ClaimTypes.NameIdentifier)!);
    static string Role(ClaimsPrincipal u)=>u.FindFirstValue(ClaimTypes.Role)??"";
    static bool Manager(ClaimsPrincipal u)=>Role(u) is "owner" or "manager";
    static bool Cashier(ClaimsPrincipal u)=>Role(u) is "owner" or "manager" or "cashier";
    static IResult Denied()=>Results.Json(new{error="Bạn không có quyền thực hiện thao tác này."},statusCode:403);
    public static async Task<bool> ExplicitlyDenied(string db,ClaimsPrincipal user,string permission)
    {
        var id=user.FindFirstValue(ClaimTypes.NameIdentifier);if(!Guid.TryParse(id,out var userId))return true;
        await using var c=new SqlConnection(db);await c.OpenAsync();await using var q=new SqlCommand("SELECT IsAllowed FROM dbo.UserPermissionOverrides WHERE UserId=@u AND PermissionKey=@p",c);q.Parameters.AddWithValue("@u",userId);q.Parameters.AddWithValue("@p",permission);var value=await q.ExecuteScalarAsync();return value is bool allowed&&!allowed;
    }

    public static void MapManagementSuite(this WebApplication app,string db)
    {
        MapMoney(app,db);MapCatalog(app,db);MapGuests(app,db);MapManagement(app,db);MapPeople(app,db);MapTaxAndStores(app,db);
    }

    static void MapMoney(WebApplication app,string db)
    {
        app.MapGet("/api/cash-movements",async(ClaimsPrincipal u)=>{if(!Cashier(u))return Denied();await using var c=new SqlConnection(db);await c.OpenAsync();var rows=new List<object>();await using var q=new SqlCommand("SELECT TOP 200 m.Id,m.ShiftId,m.MovementType,m.Amount,ISNULL(m.Category,N''),m.Reason,m.CreatedAt,ISNULL(x.FullName,N'Hệ thống') FROM dbo.CashMovements m LEFT JOIN dbo.Users x ON x.Id=m.CreatedBy JOIN dbo.WorkShifts s ON s.Id=m.ShiftId WHERE @manager=1 OR s.OpenedBy=@u ORDER BY m.CreatedAt DESC",c);q.Parameters.AddWithValue("@manager",Manager(u));q.Parameters.AddWithValue("@u",UserId(u));await using var r=await q.ExecuteReaderAsync();while(await r.ReadAsync())rows.Add(new{id=r.GetGuid(0),shiftId=r.GetGuid(1),type=r.GetString(2),amount=r.GetInt32(3),category=r.GetString(4),reason=r.GetString(5),createdAt=r.GetDateTime(6),staff=r.GetString(7)});return Results.Ok(rows);});
        app.MapPost("/api/cash-movements",async(CashMovementInput x,ClaimsPrincipal u)=>{if(!Cashier(u))return Denied();if(!new[]{"cash_in","cash_out","expense"}.Contains(x.Type)||x.Amount<=0||string.IsNullOrWhiteSpace(x.Reason))return Results.BadRequest(new{error="Phiếu thu/chi không hợp lệ."});await using var c=new SqlConnection(db);await c.OpenAsync();await using var findShift=new SqlCommand("SELECT TOP 1 Id FROM dbo.WorkShifts WHERE OpenedBy=@u AND Status='open' ORDER BY OpenedAt DESC",c);findShift.Parameters.AddWithValue("@u",UserId(u));var shift=await findShift.ExecuteScalarAsync();if(shift is null)return Results.Conflict(new{error="Hãy mở ca trước khi tạo phiếu thu/chi."});await using var q=new SqlCommand("INSERT dbo.CashMovements(ShiftId,MovementType,Amount,Category,Reason,CreatedBy) OUTPUT INSERTED.Id VALUES(@s,@t,@a,NULLIF(@c,''),@r,@u)",c);q.Parameters.AddWithValue("@s",shift);q.Parameters.AddWithValue("@t",x.Type);q.Parameters.AddWithValue("@a",x.Amount);q.Parameters.AddWithValue("@c",x.Category?.Trim()??"");q.Parameters.AddWithValue("@r",x.Reason.Trim());q.Parameters.AddWithValue("@u",UserId(u));return Results.Ok(new{id=(Guid)(await q.ExecuteScalarAsync())!});});
        app.MapPost("/api/orders/{id:guid}/mixed-payment",async(Guid id,MixedPaymentInput x,ClaimsPrincipal u)=>{if(!Cashier(u))return Denied();if(x.Payments.Count<1||x.Payments.Any(p=>p.Amount<=0||!new[]{"cash","bank_transfer","card","e_wallet"}.Contains(p.Method)))return Results.BadRequest(new{error="Danh sách thanh toán không hợp lệ."});await using var c=new SqlConnection(db);await c.OpenAsync();await using var tx=(SqlTransaction)await c.BeginTransactionAsync();var total=Convert.ToInt32(await Scalar(c,tx,"SELECT Total FROM dbo.Orders WHERE Id=@id AND Status NOT IN ('paid','cancelled')",("@id",id))??-1);if(total<0){await tx.RollbackAsync();return Results.NotFound(new{error="Đơn không còn hiệu lực."});}if(x.Payments.Sum(p=>p.Amount)!=total){await tx.RollbackAsync();return Results.BadRequest(new{error=$"Tổng các khoản thanh toán phải bằng {total:N0}đ."});}foreach(var p in x.Payments){await using var q=new SqlCommand("INSERT dbo.Payments(OrderId,Amount,Method,Reference,ReceivedBy)VALUES(@o,@a,@m,@r,@u)",c,tx);q.Parameters.AddWithValue("@o",id);q.Parameters.AddWithValue("@a",p.Amount);q.Parameters.AddWithValue("@m",p.Method);q.Parameters.AddWithValue("@r",(object?)p.Reference??DBNull.Value);q.Parameters.AddWithValue("@u",UserId(u));await q.ExecuteNonQueryAsync();}await ClosePaidOrder(c,tx,id,UserId(u));await tx.CommitAsync();return Results.Ok(new{id,total,payments=x.Payments.Count});});
        app.MapGet("/api/refunds",async(ClaimsPrincipal u)=>{if(!Cashier(u))return Denied();await using var c=new SqlConnection(db);await c.OpenAsync();var rows=new List<object>();await using var q=new SqlCommand("SELECT TOP 200 r.Id,r.OrderId,o.OrderNumber,r.Amount,r.Method,r.Reason,r.CreatedAt,ISNULL(u.FullName,N'Hệ thống') FROM dbo.Refunds r JOIN dbo.Orders o ON o.Id=r.OrderId LEFT JOIN dbo.Users u ON u.Id=r.ProcessedBy ORDER BY r.CreatedAt DESC",c);await using var rd=await q.ExecuteReaderAsync();while(await rd.ReadAsync())rows.Add(new{id=rd.GetGuid(0),orderId=rd.GetGuid(1),orderNumber=rd.GetInt64(2),amount=rd.GetInt32(3),method=rd.GetString(4),reason=rd.GetString(5),createdAt=rd.GetDateTime(6),staff=rd.GetString(7)});return Results.Ok(rows);});
        app.MapPost("/api/orders/{id:guid}/refund",async(Guid id,RefundInput x,ClaimsPrincipal u)=>{if(!Cashier(u))return Denied();if(x.Amount<=0||string.IsNullOrWhiteSpace(x.Reason)||!new[]{"cash","bank_transfer","card","e_wallet"}.Contains(x.Method))return Results.BadRequest(new{error="Số tiền, phương thức hoặc lý do hoàn không hợp lệ."});await using var c=new SqlConnection(db);await c.OpenAsync();await using var tx=(SqlTransaction)await c.BeginTransactionAsync();var paid=Convert.ToInt32(await Scalar(c,tx,"SELECT ISNULL(SUM(Amount-RefundedAmount),0) FROM dbo.Payments WHERE OrderId=@o",("@o",id))??0);if(x.Amount>paid){await tx.RollbackAsync();return Results.BadRequest(new{error=$"Chỉ còn có thể hoàn tối đa {paid:N0}đ."});}var allocations=new List<(Guid Id,int Amount)>();await using(var q=new SqlCommand("SELECT Id,Amount-RefundedAmount Remaining FROM dbo.Payments WHERE OrderId=@o AND Amount>RefundedAmount ORDER BY PaidAt DESC",c,tx)){q.Parameters.AddWithValue("@o",id);await using var r=await q.ExecuteReaderAsync();var left=x.Amount;while(left>0&&await r.ReadAsync()){var amount=Math.Min(left,r.GetInt32(1));allocations.Add((r.GetGuid(0),amount));left-=amount;}}foreach(var allocation in allocations){await Exec(c,tx,"UPDATE dbo.Payments SET RefundedAmount=RefundedAmount+@a WHERE Id=@p;INSERT dbo.Refunds(OrderId,PaymentId,Amount,Reason,Method,ProcessedBy)VALUES(@o,@p,@a,@r,@m,@u)",( "@o",id),("@p",allocation.Id),("@a",allocation.Amount),("@r",x.Reason.Trim()),("@m",x.Method),("@u",UserId(u)));}await Exec(c,tx,"DECLARE @customer uniqueidentifier=(SELECT CustomerId FROM dbo.Orders WHERE Id=@o),@points int=@a/10000;IF @customer IS NOT NULL BEGIN UPDATE dbo.Customers SET TotalSpent=CASE WHEN TotalSpent>@a THEN TotalSpent-@a ELSE 0 END,Points=CASE WHEN Points>@points THEN Points-@points ELSE 0 END WHERE Id=@customer;IF @points>0 INSERT dbo.CustomerPointTransactions(CustomerId,OrderId,Points,Reason)VALUES(@customer,@o,-@points,N'Trừ điểm do hoàn tiền') END",("@o",id),("@a",x.Amount));await tx.CommitAsync();return Results.Ok(new{id,refunded=x.Amount,remaining=paid-x.Amount});});
        app.MapPost("/api/orders/{id:guid}/split",async(Guid id,SplitOrderInput x,ClaimsPrincipal u)=>{if(!new[]{"owner","manager","cashier","server"}.Contains(Role(u)))return Denied();if(x.Items.Count==0)return Results.BadRequest(new{error="Hãy chọn món cần tách."});await using var c=new SqlConnection(db);await c.OpenAsync();await using var tx=(SqlTransaction)await c.BeginTransactionAsync();var info=await Row(c,tx,"SELECT StoreId,TableId,Discount,LoyaltyDiscount FROM dbo.Orders WHERE Id=@id AND Status NOT IN ('paid','cancelled')",("@id",id));if(info is null){await tx.RollbackAsync();return Results.NotFound(new{error="Không tìm thấy đơn."});}if(Convert.ToInt32(info["Discount"])+Convert.ToInt32(info["LoyaltyDiscount"])>0){await tx.RollbackAsync();return Results.Conflict(new{error="Hãy bỏ giảm giá trước khi tách hóa đơn."});}var newId=Guid.NewGuid();await Exec(c,tx,"INSERT dbo.Orders(Id,StoreId,TableId,Status,OpenedBy,OrderType)VALUES(@n,@s,@t,'sent',@u,'dine_in')",("@n",newId),("@s",info["StoreId"]),("@t",info["TableId"]),("@u",UserId(u)));foreach(var line in x.Items){var item=await Row(c,tx,"SELECT Quantity,ProductId,ProductName,UnitPrice,Note,Status FROM dbo.OrderItems WHERE Id=@i AND OrderId=@o AND Status='sent'",("@i",line.ItemId),("@o",id));if(item is null||line.Quantity<1||line.Quantity>Convert.ToInt16(item["Quantity"])){await tx.RollbackAsync();return Results.BadRequest(new{error="Chỉ được tách món đang chờ pha và có số lượng hợp lệ."});}if(line.Quantity==Convert.ToInt16(item["Quantity"]))await Exec(c,tx,"UPDATE dbo.OrderItems SET OrderId=@n WHERE Id=@i",("@n",newId),("@i",line.ItemId));else{var clone=Guid.NewGuid();await Exec(c,tx,"UPDATE dbo.OrderItems SET Quantity=Quantity-@q WHERE Id=@i;INSERT dbo.OrderItems(Id,OrderId,ProductId,ProductName,UnitPrice,Quantity,Note,Status)VALUES(@c,@n,@p,@name,@price,@q,@note,@status);INSERT dbo.OrderItemToppings(OrderItemId,ToppingId,Name,Price,Quantity)SELECT @c,ToppingId,Name,Price,Quantity FROM dbo.OrderItemToppings WHERE OrderItemId=@i",("@q",line.Quantity),("@i",line.ItemId),("@c",clone),("@n",newId),("@p",item["ProductId"]),("@name",item["ProductName"]),("@price",item["UnitPrice"]),("@note",item["Note"]),("@status",item["Status"]));}}await Recalculate(c,tx,id);await Recalculate(c,tx,newId);await tx.CommitAsync();return Results.Ok(new{sourceOrderId=id,newOrderId=newId});});
        app.MapPost("/api/orders/offsite",async(OffsiteOrderInput x,ClaimsPrincipal u)=>{if(!new[]{"owner","manager","cashier","server"}.Contains(Role(u)))return Denied();if(!new[]{"takeaway","delivery"}.Contains(x.OrderType)||x.Items.Count==0||x.OrderType=="delivery"&&string.IsNullOrWhiteSpace(x.DeliveryAddress))return Results.BadRequest(new{error="Thông tin đơn mang đi/giao hàng chưa đầy đủ."});await using var c=new SqlConnection(db);await c.OpenAsync();await using var tx=(SqlTransaction)await c.BeginTransactionAsync();var id=Guid.NewGuid();await Exec(c,tx,"INSERT dbo.Orders(Id,StoreId,Status,OpenedBy,OrderType,CustomerName,CustomerPhone,DeliveryAddress,FulfillmentAt)VALUES(@id,(SELECT TOP 1 Id FROM dbo.Stores WHERE IsActive=1 ORDER BY CreatedAt),'sent',@u,@type,NULLIF(@name,''),NULLIF(@phone,''),NULLIF(@address,''),@at)",( "@id",id),("@u",UserId(u)),("@type",x.OrderType),("@name",x.CustomerName?.Trim()??""),("@phone",x.CustomerPhone?.Trim()??""),("@address",x.DeliveryAddress?.Trim()??""),("@at",x.FulfillmentAt));foreach(var line in x.Items){var product=await Row(c,tx,"SELECT Name,BasePrice FROM dbo.Products WHERE Id=@id AND IsActive=1",("@id",line.ProductId));if(product is null){await tx.RollbackAsync();return Results.BadRequest(new{error="Có món không còn bán."});}var item=Guid.NewGuid();await Exec(c,tx,"INSERT dbo.OrderItems(Id,OrderId,ProductId,ProductName,UnitPrice,Quantity,Note,Status)VALUES(@i,@o,@p,@n,@price,@q,@note,'sent')",("@i",item),("@o",id),("@p",line.ProductId),("@n",product["Name"]),("@price",product["BasePrice"]),("@q",line.Quantity),("@note",line.Note));}await Recalculate(c,tx,id);await tx.CommitAsync();return Results.Ok(new{id});});
    }

    static void MapCatalog(WebApplication app,string db)
    {
        app.MapGet("/api/categories",async()=>{await using var c=new SqlConnection(db);await c.OpenAsync();return Results.Ok(await Rows(c,"SELECT Id,Name,Position,IsActive FROM dbo.Categories WHERE IsActive=1 ORDER BY Position,Name",r=>new{id=r.GetGuid(0),name=r.GetString(1),position=r.GetInt32(2),isActive=r.GetBoolean(3)}));});
        app.MapPost("/api/categories",async(CategoryInput x,ClaimsPrincipal u)=>{if(!Manager(u))return Denied();if(string.IsNullOrWhiteSpace(x.Name))return Results.BadRequest(new{error="Tên danh mục không được trống."});await using var c=new SqlConnection(db);await c.OpenAsync();await using var q=new SqlCommand("INSERT dbo.Categories(StoreId,Name,Position)OUTPUT INSERTED.Id VALUES((SELECT TOP 1 Id FROM dbo.Stores WHERE IsActive=1),@n,@p)",c);q.Parameters.AddWithValue("@n",x.Name.Trim());q.Parameters.AddWithValue("@p",x.Position);return Results.Ok(new{id=(Guid)(await q.ExecuteScalarAsync())!});});
        app.MapPut("/api/categories/{id:guid}",async(Guid id,CategoryInput x,ClaimsPrincipal u)=>{if(!Manager(u))return Denied();await using var c=new SqlConnection(db);await c.OpenAsync();return await Exec(c,null,"UPDATE dbo.Categories SET Name=@n,Position=@p WHERE Id=@id",("@n",x.Name.Trim()),("@p",x.Position),("@id",id))>0?Results.Ok(new{id}):Results.NotFound();});
        app.MapDelete("/api/categories/{id:guid}",async(Guid id,ClaimsPrincipal u)=>{if(!Manager(u))return Denied();await using var c=new SqlConnection(db);await c.OpenAsync();if(Convert.ToInt32(await Scalar(c,null,"SELECT COUNT(*) FROM dbo.Products WHERE CategoryId=@id AND IsActive=1",("@id",id)))>0)return Results.Conflict(new{error="Danh mục vẫn còn món đang bán."});await Exec(c,null,"UPDATE dbo.Categories SET IsActive=0 WHERE Id=@id",("@id",id));return Results.NoContent();});
        app.MapPut("/api/products/{id:guid}",async(Guid id,ProductEditInput x,ClaimsPrincipal u)=>{if(!Manager(u))return Denied();if(string.IsNullOrWhiteSpace(x.Name)||x.Price<0)return Results.BadRequest(new{error="Thông tin món không hợp lệ."});await using var c=new SqlConnection(db);await c.OpenAsync();return await Exec(c,null,"UPDATE dbo.Products SET Name=@n,BasePrice=@p,CategoryId=@c,SKU=NULLIF(@sku,'') WHERE Id=@id AND IsActive=1",("@n",x.Name.Trim()),("@p",x.Price),("@c",x.CategoryId),("@sku",x.Sku?.Trim()??""),("@id",id))>0?Results.Ok(new{id}):Results.NotFound();});
        app.MapGet("/api/product-variants",async()=>{await using var c=new SqlConnection(db);await c.OpenAsync();return Results.Ok(await Rows(c,"SELECT Id,ProductId,Name,PriceDelta,Position FROM dbo.ProductVariants WHERE IsActive=1 ORDER BY ProductId,Position",r=>new{id=r.GetGuid(0),productId=r.GetGuid(1),name=r.GetString(2),priceDelta=r.GetInt32(3),position=r.GetInt32(4)}));});
        app.MapPost("/api/product-variants",async(VariantInput x,ClaimsPrincipal u)=>{if(!Manager(u))return Denied();await using var c=new SqlConnection(db);await c.OpenAsync();await using var q=new SqlCommand("INSERT dbo.ProductVariants(ProductId,Name,PriceDelta,Position)OUTPUT INSERTED.Id VALUES(@p,@n,@d,@o)",c);q.Parameters.AddWithValue("@p",x.ProductId);q.Parameters.AddWithValue("@n",x.Name.Trim());q.Parameters.AddWithValue("@d",x.PriceDelta);q.Parameters.AddWithValue("@o",x.Position);return Results.Ok(new{id=(Guid)(await q.ExecuteScalarAsync())!});});
        app.MapPut("/api/product-variants/{id:guid}",async(Guid id,VariantInput x,ClaimsPrincipal u)=>{if(!Manager(u))return Denied();if(string.IsNullOrWhiteSpace(x.Name))return Results.BadRequest(new{error="Tên lựa chọn không được trống."});await using var c=new SqlConnection(db);await c.OpenAsync();return await Exec(c,null,"UPDATE dbo.ProductVariants SET ProductId=@p,Name=@n,PriceDelta=@d,Position=@o WHERE Id=@id AND IsActive=1",("@p",x.ProductId),("@n",x.Name.Trim()),("@d",x.PriceDelta),("@o",x.Position),("@id",id))>0?Results.Ok(new{id}):Results.NotFound();});
        app.MapDelete("/api/product-variants/{id:guid}",async(Guid id,ClaimsPrincipal u)=>{if(!Manager(u))return Denied();await using var c=new SqlConnection(db);await c.OpenAsync();await Exec(c,null,"UPDATE dbo.ProductVariants SET IsActive=0 WHERE Id=@id",("@id",id));return Results.NoContent();});
        app.MapGet("/api/combos",async()=>{await using var c=new SqlConnection(db);await c.OpenAsync();return Results.Ok(await Rows(c,"SELECT Id,Name,Price,IsActive,StartsAt,EndsAt FROM dbo.Combos WHERE IsActive=1 ORDER BY Name",r=>new{id=r.GetGuid(0),name=r.GetString(1),price=r.GetInt32(2),isActive=r.GetBoolean(3),startsAt=r.IsDBNull(4)?(DateTime?)null:r.GetDateTime(4),endsAt=r.IsDBNull(5)?(DateTime?)null:r.GetDateTime(5)}));});
        app.MapPost("/api/combos",async(ComboInput x,ClaimsPrincipal u)=>{if(!Manager(u))return Denied();if(string.IsNullOrWhiteSpace(x.Name)||x.Price<0||x.Items.Count==0)return Results.BadRequest(new{error="Combo không hợp lệ."});await using var c=new SqlConnection(db);await c.OpenAsync();await using var tx=(SqlTransaction)await c.BeginTransactionAsync();var id=Guid.NewGuid();await Exec(c,tx,"INSERT dbo.Combos(Id,StoreId,Name,Price,StartsAt,EndsAt)VALUES(@id,(SELECT TOP 1 Id FROM dbo.Stores WHERE IsActive=1),@n,@p,@s,@e)",( "@id",id),("@n",x.Name.Trim()),("@p",x.Price),("@s",x.StartsAt),("@e",x.EndsAt));foreach(var i in x.Items)await Exec(c,tx,"INSERT dbo.ComboItems(ComboId,ProductId,Quantity)VALUES(@c,@p,@q)",( "@c",id),("@p",i.ProductId),("@q",i.Quantity));await tx.CommitAsync();return Results.Ok(new{id});});
        app.MapPut("/api/combos/{id:guid}",async(Guid id,ComboInput x,ClaimsPrincipal u)=>{if(!Manager(u))return Denied();if(string.IsNullOrWhiteSpace(x.Name)||x.Price<0||x.Items.Count==0)return Results.BadRequest(new{error="Combo không hợp lệ."});await using var c=new SqlConnection(db);await c.OpenAsync();await using var tx=(SqlTransaction)await c.BeginTransactionAsync();await Exec(c,tx,"UPDATE dbo.Combos SET Name=@n,Price=@p,StartsAt=@s,EndsAt=@e WHERE Id=@id;DELETE dbo.ComboItems WHERE ComboId=@id",("@id",id),("@n",x.Name.Trim()),("@p",x.Price),("@s",x.StartsAt),("@e",x.EndsAt));foreach(var i in x.Items)await Exec(c,tx,"INSERT dbo.ComboItems(ComboId,ProductId,Quantity)VALUES(@c,@p,@q)",( "@c",id),("@p",i.ProductId),("@q",i.Quantity));await tx.CommitAsync();return Results.Ok(new{id});});
        app.MapDelete("/api/combos/{id:guid}",async(Guid id,ClaimsPrincipal u)=>{if(!Manager(u))return Denied();await using var c=new SqlConnection(db);await c.OpenAsync();await Exec(c,null,"UPDATE dbo.Combos SET IsActive=0 WHERE Id=@id",("@id",id));return Results.NoContent();});
        app.MapPut("/api/promotions/{id:guid}",async(Guid id,PromotionEditInput x,ClaimsPrincipal u)=>{if(!Manager(u))return Denied();if(string.IsNullOrWhiteSpace(x.Code)||string.IsNullOrWhiteSpace(x.Name)||!new[]{"percent","fixed"}.Contains(x.Type)||x.Value<=0)return Results.BadRequest(new{error="Khuyến mãi không hợp lệ."});await using var c=new SqlConnection(db);await c.OpenAsync();try{var n=await Exec(c,null,"UPDATE dbo.Promotions SET Code=UPPER(@code),Name=@name,Type=@type,Value=@value,MinimumOrder=@min,MaximumDiscount=@max,StartsAt=@start,EndsAt=@end,UsageLimit=@limit,PerCustomerLimit=@per,IsActive=@active WHERE Id=@id",("@id",id),("@code",x.Code.Trim()),("@name",x.Name.Trim()),("@type",x.Type),("@value",x.Value),("@min",x.MinimumOrder),("@max",x.MaximumDiscount),("@start",x.StartsAt),("@end",x.EndsAt),("@limit",x.UsageLimit),("@per",x.PerCustomerLimit),("@active",x.IsActive));return n>0?Results.Ok(new{id}):Results.NotFound();}catch(SqlException){return Results.Conflict(new{error="Mã khuyến mãi đã tồn tại."});}});
        app.MapPatch("/api/promotions/{id:guid}/status",async(Guid id,ActiveInput x,ClaimsPrincipal u)=>{if(!Manager(u))return Denied();await using var c=new SqlConnection(db);await c.OpenAsync();await Exec(c,null,"UPDATE dbo.Promotions SET IsActive=@a WHERE Id=@id",("@a",x.IsActive),("@id",id));return Results.Ok(new{id,isActive=x.IsActive});});
        app.MapDelete("/api/promotions/{id:guid}",async(Guid id,ClaimsPrincipal u)=>{if(!Manager(u))return Denied();await using var c=new SqlConnection(db);await c.OpenAsync();await Exec(c,null,"UPDATE dbo.Promotions SET IsActive=0 WHERE Id=@id",("@id",id));return Results.NoContent();});
    }

    static void MapGuests(WebApplication app,string db)
    {
        app.MapGet("/api/reservations",async(DateTime? date)=>{await using var c=new SqlConnection(db);await c.OpenAsync();var day=(date??DateTime.UtcNow.AddHours(7)).Date.AddHours(-7);return Results.Ok(await Rows(c,"SELECT r.Id,r.CustomerName,r.Phone,r.GuestCount,r.ReservedAt,r.Status,ISNULL(r.Note,N''),r.TableId,ISNULL(t.Code,N'Chưa xếp bàn') FROM dbo.Reservations r LEFT JOIN dbo.DiningTables t ON t.Id=r.TableId WHERE r.ReservedAt>=@d AND r.ReservedAt<DATEADD(day,1,@d) ORDER BY r.ReservedAt",r=>new{id=r.GetGuid(0),customerName=r.GetString(1),phone=r.GetString(2),guestCount=r.GetInt16(3),reservedAt=r.GetDateTime(4),status=r.GetString(5),note=r.GetString(6),tableId=r.IsDBNull(7)?(Guid?)null:r.GetGuid(7),tableName=r.GetString(8)},("@d",day)));});
        app.MapPost("/api/reservations",async(ReservationInput x,ClaimsPrincipal u)=>{if(!new[]{"owner","manager","cashier","server"}.Contains(Role(u)))return Denied();if(string.IsNullOrWhiteSpace(x.CustomerName)||string.IsNullOrWhiteSpace(x.Phone)||x.GuestCount<1)return Results.BadRequest(new{error="Thông tin đặt bàn không hợp lệ."});await using var c=new SqlConnection(db);await c.OpenAsync();await using var q=new SqlCommand("INSERT dbo.Reservations(StoreId,TableId,CustomerName,Phone,GuestCount,ReservedAt,Note,CreatedBy)OUTPUT INSERTED.Id VALUES((SELECT TOP 1 Id FROM dbo.Stores WHERE IsActive=1),@t,@n,@p,@g,@at,@note,@u)",c);q.Parameters.AddWithValue("@t",(object?)x.TableId??DBNull.Value);q.Parameters.AddWithValue("@n",x.CustomerName.Trim());q.Parameters.AddWithValue("@p",x.Phone.Trim());q.Parameters.AddWithValue("@g",x.GuestCount);q.Parameters.AddWithValue("@at",x.ReservedAt);q.Parameters.AddWithValue("@note",(object?)x.Note??DBNull.Value);q.Parameters.AddWithValue("@u",UserId(u));return Results.Ok(new{id=(Guid)(await q.ExecuteScalarAsync())!});});
        app.MapPatch("/api/reservations/{id:guid}/status",async(Guid id,StatusOnlyInput x,ClaimsPrincipal u)=>{if(!new[]{"owner","manager","cashier","server"}.Contains(Role(u)))return Denied();if(!new[]{"booked","confirmed","arrived","seated","cancelled","no_show"}.Contains(x.Status))return Results.BadRequest(new{error="Trạng thái không hợp lệ."});await using var c=new SqlConnection(db);await c.OpenAsync();await using var tx=(SqlTransaction)await c.BeginTransactionAsync();if(x.Status=="seated"&&Convert.ToInt32(await Scalar(c,tx,"SELECT COUNT(*) FROM dbo.Reservations r JOIN dbo.DiningTables t ON t.Id=r.TableId WHERE r.Id=@id AND t.Status IN ('available','reserved')",("@id",id)))==0){await tx.RollbackAsync();return Results.Conflict(new{error="Lịch đặt chưa có bàn trống để xếp khách."});}await Exec(c,tx,"UPDATE dbo.Reservations SET Status=@s WHERE Id=@id;IF @s='confirmed' UPDATE dbo.DiningTables SET Status='reserved' WHERE Id=(SELECT TableId FROM dbo.Reservations WHERE Id=@id) AND Status='available';IF @s='seated' UPDATE dbo.DiningTables SET Status='occupied' WHERE Id=(SELECT TableId FROM dbo.Reservations WHERE Id=@id);IF @s IN ('cancelled','no_show') UPDATE dbo.DiningTables SET Status='available' WHERE Id=(SELECT TableId FROM dbo.Reservations WHERE Id=@id) AND NOT EXISTS(SELECT 1 FROM dbo.Orders WHERE TableId=dbo.DiningTables.Id AND Status NOT IN ('paid','cancelled'))",("@s",x.Status),("@id",id));await tx.CommitAsync();return Results.Ok(new{id,status=x.Status});});
        app.MapGet("/api/waitlist",async()=>{await using var c=new SqlConnection(db);await c.OpenAsync();return Results.Ok(await Rows(c,"SELECT Id,CustomerName,ISNULL(Phone,N''),GuestCount,Status,ISNULL(Note,N''),CreatedAt FROM dbo.Waitlist WHERE Status='waiting' ORDER BY CreatedAt",r=>new{id=r.GetGuid(0),customerName=r.GetString(1),phone=r.GetString(2),guestCount=r.GetInt16(3),status=r.GetString(4),note=r.GetString(5),createdAt=r.GetDateTime(6)}));});
        app.MapPost("/api/waitlist",async(WaitlistInput x)=>{if(string.IsNullOrWhiteSpace(x.CustomerName)||x.GuestCount<1)return Results.BadRequest(new{error="Thông tin khách chờ không hợp lệ."});await using var c=new SqlConnection(db);await c.OpenAsync();await using var q=new SqlCommand("INSERT dbo.Waitlist(StoreId,CustomerName,Phone,GuestCount,Note)OUTPUT INSERTED.Id VALUES((SELECT TOP 1 Id FROM dbo.Stores WHERE IsActive=1),@n,NULLIF(@p,''),@g,NULLIF(@note,''))",c);q.Parameters.AddWithValue("@n",x.CustomerName.Trim());q.Parameters.AddWithValue("@p",x.Phone?.Trim()??"");q.Parameters.AddWithValue("@g",x.GuestCount);q.Parameters.AddWithValue("@note",x.Note?.Trim()??"");return Results.Ok(new{id=(Guid)(await q.ExecuteScalarAsync())!});});
        app.MapPatch("/api/waitlist/{id:guid}/seat",async(Guid id)=>{await using var c=new SqlConnection(db);await c.OpenAsync();await Exec(c,null,"UPDATE dbo.Waitlist SET Status='seated',SeatedAt=SYSUTCDATETIME() WHERE Id=@id",("@id",id));return Results.Ok(new{id});});
        app.MapGet("/api/customers/{id:guid}/profile",async(Guid id)=>{await using var c=new SqlConnection(db);await c.OpenAsync();var customer=await Row(c,null,"SELECT Id,FullName,Phone,ISNULL(Email,N'') Email,Birthday,Tier,Points,TotalSpent,CreatedAt FROM dbo.Customers WHERE Id=@id",("@id",id));if(customer is null)return Results.NotFound();var orders=await Rows(c,"SELECT TOP 50 Id,OrderNumber,Total,Status,OpenedAt FROM dbo.Orders WHERE CustomerId=@id ORDER BY OpenedAt DESC",r=>new{id=r.GetGuid(0),orderNumber=r.GetInt64(1),total=r.GetInt32(2),status=r.GetString(3),openedAt=r.GetDateTime(4)},("@id",id));var points=await Rows(c,"SELECT TOP 100 Points,Reason,ExpiresAt,CreatedAt FROM dbo.CustomerPointTransactions WHERE CustomerId=@id ORDER BY CreatedAt DESC",r=>new{points=r.GetInt32(0),reason=r.GetString(1),expiresAt=r.IsDBNull(2)?(DateTime?)null:r.GetDateTime(2),createdAt=r.GetDateTime(3)},("@id",id));return Results.Ok(new{customer,orders,pointHistory=points});});
        app.MapPut("/api/customers/{id:guid}",async(Guid id,CustomerProfileInput x)=>{await using var c=new SqlConnection(db);await c.OpenAsync();await Exec(c,null,"UPDATE dbo.Customers SET FullName=@n,Phone=@p,Email=NULLIF(@e,''),Birthday=@b,Tier=@t WHERE Id=@id",("@n",x.Name.Trim()),("@p",x.Phone.Trim()),("@e",x.Email?.Trim()??""),("@b",x.Birthday),("@t",x.Tier),("@id",id));return Results.Ok(new{id});});
        app.MapPost("/api/customers/{id:guid}/points",async(Guid id,PointAdjustmentInput x,ClaimsPrincipal u)=>{if(!Manager(u))return Denied();if(x.Points==0||string.IsNullOrWhiteSpace(x.Reason))return Results.BadRequest(new{error="Điểm và lý do không hợp lệ."});await using var c=new SqlConnection(db);await c.OpenAsync();await using var tx=(SqlTransaction)await c.BeginTransactionAsync();await Exec(c,tx,"UPDATE dbo.Customers SET Points=CASE WHEN Points+@p<0 THEN 0 ELSE Points+@p END WHERE Id=@id;INSERT dbo.CustomerPointTransactions(CustomerId,Points,Reason,ExpiresAt)VALUES(@id,@p,@r,@e)",( "@id",id),("@p",x.Points),("@r",x.Reason.Trim()),("@e",x.ExpiresAt));await tx.CommitAsync();return Results.Ok(new{id});});
    }

    static void MapManagement(WebApplication app,string db)
    {
        app.MapGet("/api/reports/advanced",async(DateTime? from,DateTime? to,ClaimsPrincipal u)=>{if(!Manager(u))return Denied();var start=(from??DateTime.UtcNow.AddHours(7).Date.AddDays(-29)).Date.AddHours(-7);var end=(to??DateTime.UtcNow.AddHours(7).Date).Date.AddDays(1).AddHours(-7);await using var c=new SqlConnection(db);await c.OpenAsync();var daily=await Rows(c,"SELECT CONVERT(date,DATEADD(hour,7,p.PaidAt)),SUM(p.Amount-p.RefundedAmount),COUNT(DISTINCT p.OrderId) FROM dbo.Payments p WHERE p.PaidAt>=@f AND p.PaidAt<@t GROUP BY CONVERT(date,DATEADD(hour,7,p.PaidAt)) ORDER BY 1",r=>new{date=r.GetDateTime(0),revenue=r.GetInt32(1),orders=r.GetInt32(2)},("@f",start),("@t",end));var products=await Rows(c,"SELECT TOP 20 i.ProductName,SUM(CONVERT(int,i.Quantity)),SUM((i.UnitPrice+ISNULL(x.TopPrice,0))*i.Quantity) FROM dbo.OrderItems i JOIN dbo.Orders o ON o.Id=i.OrderId OUTER APPLY(SELECT SUM(Price*Quantity) TopPrice FROM dbo.OrderItemToppings WHERE OrderItemId=i.Id)x WHERE o.Status='paid' AND o.ClosedAt>=@f AND o.ClosedAt<@t AND i.Status<>'cancelled' GROUP BY i.ProductName ORDER BY 3 DESC",r=>new{name=r.GetString(0),quantity=r.GetInt32(1),revenue=r.GetInt32(2)},("@f",start),("@t",end));var payments=await Rows(c,"SELECT Method,SUM(Amount-RefundedAmount) FROM dbo.Payments WHERE PaidAt>=@f AND PaidAt<@t GROUP BY Method",r=>new{method=r.GetString(0),amount=r.GetInt32(1)},("@f",start),("@t",end));var sales=Convert.ToInt32(await Scalar(c,null,"SELECT ISNULL(SUM(Amount-RefundedAmount),0) FROM dbo.Payments WHERE PaidAt>=@f AND PaidAt<@t",("@f",start),("@t",end))??0);var cost=Convert.ToDecimal(await Scalar(c,null,"SELECT ISNULL(SUM(ABS(QuantityChange)*ISNULL(UnitCost,0)),0) FROM dbo.StockMovements WHERE MovementType='consumption' AND CreatedAt>=@f AND CreatedAt<@t",("@f",start),("@t",end))??0);var expenses=Convert.ToInt32(await Scalar(c,null,"SELECT ISNULL(SUM(Amount),0) FROM dbo.CashMovements WHERE MovementType='expense' AND CreatedAt>=@f AND CreatedAt<@t",("@f",start),("@t",end))??0);return Results.Ok(new{from=start,to=end,sales,cost,expenses,grossProfit=sales-cost-expenses,daily,products,payments});});
        app.MapGet("/api/purchase-orders",async(ClaimsPrincipal u)=>{if(!Manager(u))return Denied();await using var c=new SqlConnection(db);await c.OpenAsync();return Results.Ok(await Rows(c,"SELECT TOP 100 p.Id,p.OrderNumber,p.Status,p.TotalCost,p.ExpectedAt,p.CreatedAt,ISNULL(s.Name,N'Không chọn NCC') FROM dbo.PurchaseOrders p LEFT JOIN dbo.Suppliers s ON s.Id=p.SupplierId ORDER BY p.CreatedAt DESC",r=>new{id=r.GetGuid(0),orderNumber=r.GetInt64(1),status=r.GetString(2),totalCost=r.GetDecimal(3),expectedAt=r.IsDBNull(4)?(DateTime?)null:r.GetDateTime(4),createdAt=r.GetDateTime(5),supplier=r.GetString(6)}));});
        app.MapPost("/api/purchase-orders",async(PurchaseOrderInput x,ClaimsPrincipal u)=>{if(!Manager(u))return Denied();if(x.Items.Count==0)return Results.BadRequest(new{error="Đơn mua hàng chưa có nguyên liệu."});await using var c=new SqlConnection(db);await c.OpenAsync();await using var tx=(SqlTransaction)await c.BeginTransactionAsync();var id=Guid.NewGuid();var total=x.Items.Sum(i=>i.Quantity*i.UnitCost);await Exec(c,tx,"INSERT dbo.PurchaseOrders(Id,StoreId,SupplierId,ExpectedAt,TotalCost,Note,CreatedBy)VALUES(@id,(SELECT TOP 1 Id FROM dbo.Stores WHERE IsActive=1),@s,@e,@total,@n,@u)",( "@id",id),("@s",x.SupplierId),("@e",x.ExpectedAt),("@total",total),("@n",x.Note),("@u",UserId(u)));foreach(var i in x.Items)await Exec(c,tx,"INSERT dbo.PurchaseOrderItems(PurchaseOrderId,IngredientId,Quantity,UnitCost)VALUES(@o,@i,@q,@c)",( "@o",id),("@i",i.IngredientId),("@q",i.Quantity),("@c",i.UnitCost));await tx.CommitAsync();return Results.Ok(new{id,total});});
        app.MapPatch("/api/purchase-orders/{id:guid}/status",async(Guid id,StatusOnlyInput x,ClaimsPrincipal u)=>{if(!Manager(u))return Denied();if(!new[]{"draft","ordered","received","cancelled"}.Contains(x.Status))return Results.BadRequest();await using var c=new SqlConnection(db);await c.OpenAsync();await using var tx=(SqlTransaction)await c.BeginTransactionAsync();var current=(string?)await Scalar(c,tx,"SELECT Status FROM dbo.PurchaseOrders WHERE Id=@id",("@id",id));if(current is null){await tx.RollbackAsync();return Results.NotFound();}if(current=="received"&&x.Status!="received"){await tx.RollbackAsync();return Results.Conflict(new{error="Đơn đã nhập kho nên không thể đổi lại trạng thái."});}if(x.Status=="received"&&current!="received"){await Exec(c,tx,@"UPDATE i SET AverageCost=CASE WHEN i.Quantity+p.Quantity=0 THEN i.AverageCost ELSE (i.Quantity*i.AverageCost+p.Quantity*p.UnitCost)/(i.Quantity+p.Quantity) END,Quantity=i.Quantity+p.Quantity FROM dbo.Ingredients i JOIN dbo.PurchaseOrderItems p ON p.IngredientId=i.Id WHERE p.PurchaseOrderId=@id;
INSERT dbo.StockMovements(IngredientId,QuantityChange,Reason,CreatedBy,MovementType,ReferenceType,ReferenceId,UnitCost,BalanceAfter) SELECT p.IngredientId,p.Quantity,N'Nhập từ đơn mua #'+CONVERT(nvarchar(20),o.OrderNumber),@u,N'receipt',N'purchase_order',@id,p.UnitCost,i.Quantity FROM dbo.PurchaseOrderItems p JOIN dbo.PurchaseOrders o ON o.Id=p.PurchaseOrderId JOIN dbo.Ingredients i ON i.Id=p.IngredientId WHERE p.PurchaseOrderId=@id;
INSERT dbo.IngredientLots(IngredientId,Quantity,StockReceiptId) SELECT IngredientId,Quantity,NULL FROM dbo.PurchaseOrderItems WHERE PurchaseOrderId=@id",("@id",id),("@u",UserId(u)));}await Exec(c,tx,"UPDATE dbo.PurchaseOrders SET Status=@s WHERE Id=@id",("@s",x.Status),("@id",id));await tx.CommitAsync();return Results.Ok(new{id,status=x.Status});});
        app.MapGet("/api/inventory/lots",async(ClaimsPrincipal u)=>{if(!Manager(u))return Denied();await using var c=new SqlConnection(db);await c.OpenAsync();return Results.Ok(await Rows(c,"SELECT l.Id,i.Name,ISNULL(l.LotCode,N''),l.Quantity,l.ExpiresAt,l.ReceivedAt FROM dbo.IngredientLots l JOIN dbo.Ingredients i ON i.Id=l.IngredientId WHERE l.Quantity>0 ORDER BY CASE WHEN l.ExpiresAt IS NULL THEN 1 ELSE 0 END,l.ExpiresAt",r=>new{id=r.GetGuid(0),ingredient=r.GetString(1),lotCode=r.GetString(2),quantity=r.GetDecimal(3),expiresAt=r.IsDBNull(4)?(DateTime?)null:r.GetDateTime(4),receivedAt=r.GetDateTime(5)}));});
        app.MapPost("/api/inventory/lots",async(IngredientLotInput x,ClaimsPrincipal u)=>{if(!Manager(u))return Denied();if(x.Quantity<=0)return Results.BadRequest();await using var c=new SqlConnection(db);await c.OpenAsync();await using var q=new SqlCommand("INSERT dbo.IngredientLots(IngredientId,LotCode,Quantity,ExpiresAt)OUTPUT INSERTED.Id VALUES(@i,NULLIF(@l,''),@q,@e)",c);q.Parameters.AddWithValue("@i",x.IngredientId);q.Parameters.AddWithValue("@l",x.LotCode?.Trim()??"");q.Parameters.AddWithValue("@q",x.Quantity);q.Parameters.AddWithValue("@e",(object?)x.ExpiresAt??DBNull.Value);return Results.Ok(new{id=(Guid)(await q.ExecuteScalarAsync())!});});
        app.MapGet("/api/supplier-balances",async(ClaimsPrincipal u)=>{if(!Manager(u))return Denied();await using var c=new SqlConnection(db);await c.OpenAsync();return Results.Ok(await Rows(c,"SELECT s.Id,s.Name,ISNULL(po.Purchased,0),ISNULL(pay.Paid,0),ISNULL(po.Purchased,0)-ISNULL(pay.Paid,0) Balance FROM dbo.Suppliers s OUTER APPLY(SELECT SUM(TotalCost) Purchased FROM dbo.PurchaseOrders WHERE SupplierId=s.Id AND Status<>'cancelled')po OUTER APPLY(SELECT SUM(Amount) Paid FROM dbo.SupplierPayments WHERE SupplierId=s.Id)pay WHERE s.IsActive=1 ORDER BY s.Name",r=>new{supplierId=r.GetGuid(0),supplier=r.GetString(1),purchased=r.GetDecimal(2),paid=r.GetDecimal(3),balance=r.GetDecimal(4)}));});
        app.MapGet("/api/supplier-payments",async(ClaimsPrincipal u)=>{if(!Manager(u))return Denied();await using var c=new SqlConnection(db);await c.OpenAsync();return Results.Ok(await Rows(c,"SELECT TOP 200 p.Id,p.SupplierId,s.Name,p.PurchaseOrderId,p.Amount,p.Method,ISNULL(p.Note,N''),p.PaidAt FROM dbo.SupplierPayments p JOIN dbo.Suppliers s ON s.Id=p.SupplierId ORDER BY p.PaidAt DESC",r=>new{id=r.GetGuid(0),supplierId=r.GetGuid(1),supplier=r.GetString(2),purchaseOrderId=r.IsDBNull(3)?(Guid?)null:r.GetGuid(3),amount=r.GetDecimal(4),method=r.GetString(5),note=r.GetString(6),paidAt=r.GetDateTime(7)}));});
        app.MapPost("/api/supplier-payments",async(SupplierPaymentInput x,ClaimsPrincipal u)=>{if(!Manager(u))return Denied();if(x.Amount<=0||!new[]{"cash","bank_transfer","card"}.Contains(x.Method))return Results.BadRequest(new{error="Phiếu trả nhà cung cấp không hợp lệ."});await using var c=new SqlConnection(db);await c.OpenAsync();await using var q=new SqlCommand("INSERT dbo.SupplierPayments(SupplierId,PurchaseOrderId,Amount,Method,Note,CreatedBy)OUTPUT INSERTED.Id VALUES(@s,@po,@a,@m,NULLIF(@n,''),@u)",c);q.Parameters.AddWithValue("@s",x.SupplierId);q.Parameters.AddWithValue("@po",(object?)x.PurchaseOrderId??DBNull.Value);q.Parameters.AddWithValue("@a",x.Amount);q.Parameters.AddWithValue("@m",x.Method);q.Parameters.AddWithValue("@n",x.Note?.Trim()??"");q.Parameters.AddWithValue("@u",UserId(u));return Results.Ok(new{id=(Guid)(await q.ExecuteScalarAsync())!});});
    }

    static void MapPeople(WebApplication app,string db)
    {
        app.MapGet("/api/staff-directory",async(ClaimsPrincipal u)=>{if(!Manager(u))return Denied();await using var c=new SqlConnection(db);await c.OpenAsync();return Results.Ok(await Rows(c,"SELECT Id,FullName,Role FROM dbo.Users WHERE IsActive=1 ORDER BY FullName",r=>new{id=r.GetGuid(0),name=r.GetString(1),role=r.GetString(2)}));});
        app.MapGet("/api/schedules",async(DateTime? from,DateTime? to,ClaimsPrincipal u)=>{if(!Manager(u)&&Role(u)!="server"&&Role(u)!="barista"&&Role(u)!="cashier")return Denied();var f=from??DateTime.UtcNow.Date.AddDays(-1);var t=to??f.AddDays(15);await using var c=new SqlConnection(db);await c.OpenAsync();return Results.Ok(await Rows(c,"SELECT s.Id,s.UserId,u.FullName,s.StartsAt,s.EndsAt,s.HourlyRate,ISNULL(s.Note,N''),s.Status FROM dbo.WorkSchedules s JOIN dbo.Users u ON u.Id=s.UserId WHERE s.StartsAt>=@f AND s.StartsAt<@t AND (@manager=1 OR s.UserId=@u) ORDER BY s.StartsAt",r=>new{id=r.GetGuid(0),userId=r.GetGuid(1),staff=r.GetString(2),startsAt=r.GetDateTime(3),endsAt=r.GetDateTime(4),hourlyRate=r.GetDecimal(5),note=r.GetString(6),status=r.GetString(7)},("@f",f),("@t",t),("@manager",Manager(u)),("@u",UserId(u))));});
        app.MapPost("/api/schedules",async(ScheduleInput x,ClaimsPrincipal u)=>{if(!Manager(u))return Denied();if(x.EndsAt<=x.StartsAt)return Results.BadRequest(new{error="Giờ kết thúc phải sau giờ bắt đầu."});await using var c=new SqlConnection(db);await c.OpenAsync();await using var q=new SqlCommand("INSERT dbo.WorkSchedules(UserId,StoreId,StartsAt,EndsAt,HourlyRate,Note)OUTPUT INSERTED.Id VALUES(@u,(SELECT TOP 1 Id FROM dbo.Stores WHERE IsActive=1),@s,@e,@rate,@n)",c);q.Parameters.AddWithValue("@u",x.UserId);q.Parameters.AddWithValue("@s",x.StartsAt);q.Parameters.AddWithValue("@e",x.EndsAt);q.Parameters.AddWithValue("@rate",x.HourlyRate);q.Parameters.AddWithValue("@n",(object?)x.Note??DBNull.Value);return Results.Ok(new{id=(Guid)(await q.ExecuteScalarAsync())!});});
        app.MapDelete("/api/schedules/{id:guid}",async(Guid id,ClaimsPrincipal u)=>{if(!Manager(u))return Denied();await using var c=new SqlConnection(db);await c.OpenAsync();await Exec(c,null,"DELETE dbo.WorkSchedules WHERE Id=@id",("@id",id));return Results.NoContent();});
        app.MapGet("/api/attendance/current",async(ClaimsPrincipal u)=>{await using var c=new SqlConnection(db);await c.OpenAsync();var row=await Row(c,null,"SELECT TOP 1 Id,CheckInAt,CheckOutAt,ISNULL(Note,N'') FROM dbo.AttendanceEntries WHERE UserId=@u AND CheckOutAt IS NULL ORDER BY CheckInAt DESC",("@u",UserId(u)));return Results.Ok(row);});
        app.MapPost("/api/attendance/check-in",async(ClaimsPrincipal u)=>{await using var c=new SqlConnection(db);await c.OpenAsync();if(Convert.ToInt32(await Scalar(c,null,"SELECT COUNT(*) FROM dbo.AttendanceEntries WHERE UserId=@u AND CheckOutAt IS NULL",("@u",UserId(u))))>0)return Results.Conflict(new{error="Bạn đã chấm công vào ca."});await using var q=new SqlCommand("INSERT dbo.AttendanceEntries(UserId,StoreId)OUTPUT INSERTED.Id,INSERTED.CheckInAt VALUES(@u,(SELECT TOP 1 Id FROM dbo.Stores WHERE IsActive=1))",c);q.Parameters.AddWithValue("@u",UserId(u));await using var r=await q.ExecuteReaderAsync();await r.ReadAsync();return Results.Ok(new{id=r.GetGuid(0),checkInAt=r.GetDateTime(1)});});
        app.MapPost("/api/attendance/check-out",async(ClaimsPrincipal u)=>{await using var c=new SqlConnection(db);await c.OpenAsync();await using var q=new SqlCommand("UPDATE dbo.AttendanceEntries SET CheckOutAt=SYSUTCDATETIME() OUTPUT INSERTED.Id,INSERTED.CheckInAt,INSERTED.CheckOutAt WHERE Id=(SELECT TOP 1 Id FROM dbo.AttendanceEntries WHERE UserId=@u AND CheckOutAt IS NULL ORDER BY CheckInAt DESC)",c);q.Parameters.AddWithValue("@u",UserId(u));await using var r=await q.ExecuteReaderAsync();if(!await r.ReadAsync())return Results.Conflict(new{error="Bạn chưa chấm công vào ca."});return Results.Ok(new{id=r.GetGuid(0),checkInAt=r.GetDateTime(1),checkOutAt=r.GetDateTime(2)});});
        app.MapGet("/api/attendance/report",async(DateTime? from,DateTime? to,ClaimsPrincipal u)=>{if(!Manager(u))return Denied();var f=from??DateTime.UtcNow.Date.AddDays(-30);var t=to??DateTime.UtcNow.AddDays(1);await using var c=new SqlConnection(db);await c.OpenAsync();return Results.Ok(await Rows(c,"SELECT u.Id,u.FullName,SUM(DATEDIFF(minute,a.CheckInAt,ISNULL(a.CheckOutAt,SYSUTCDATETIME())))/60.0 Hours,ISNULL(SUM(DATEDIFF(minute,a.CheckInAt,ISNULL(a.CheckOutAt,SYSUTCDATETIME()))/60.0*ISNULL(s.HourlyRate,0)),0) Salary FROM dbo.AttendanceEntries a JOIN dbo.Users u ON u.Id=a.UserId OUTER APPLY(SELECT TOP 1 HourlyRate FROM dbo.WorkSchedules WHERE UserId=a.UserId AND a.CheckInAt BETWEEN StartsAt AND EndsAt ORDER BY StartsAt DESC)s WHERE a.CheckInAt>=@f AND a.CheckInAt<@t GROUP BY u.Id,u.FullName ORDER BY u.FullName",r=>new{userId=r.GetGuid(0),staff=r.GetString(1),hours=r.GetDecimal(2),estimatedSalary=r.GetDecimal(3)},("@f",f),("@t",t)));});
        app.MapGet("/api/permissions/catalog",()=>Results.Ok(Permissions));
        app.MapGet("/api/users/{id:guid}/permissions",async(Guid id,ClaimsPrincipal u)=>{if(Role(u)!="owner")return Denied();await using var c=new SqlConnection(db);await c.OpenAsync();return Results.Ok(await Rows(c,"SELECT PermissionKey,IsAllowed FROM dbo.UserPermissionOverrides WHERE UserId=@id",r=>new{key=r.GetString(0),isAllowed=r.GetBoolean(1)},("@id",id)));});
        app.MapPut("/api/users/{id:guid}/permissions",async(Guid id,PermissionOverrideInput x,ClaimsPrincipal u)=>{if(Role(u)!="owner")return Denied();await using var c=new SqlConnection(db);await c.OpenAsync();await using var tx=(SqlTransaction)await c.BeginTransactionAsync();await Exec(c,tx,"DELETE dbo.UserPermissionOverrides WHERE UserId=@id",("@id",id));foreach(var p in x.Items.Where(p=>Permissions.Any(permission=>permission.Key==p.Key)))await Exec(c,tx,"INSERT dbo.UserPermissionOverrides(UserId,PermissionKey,IsAllowed)VALUES(@id,@k,@a)",( "@id",id),("@k",p.Key),("@a",p.IsAllowed));await Exec(c,tx,"UPDATE dbo.Users SET AuthVersion=AuthVersion+1 WHERE Id=@id",("@id",id));await tx.CommitAsync();return Results.Ok(new{id,count=x.Items.Count});});
    }

    static void MapTaxAndStores(WebApplication app,string db)
    {
        app.MapGet("/api/tax-settings",async(ClaimsPrincipal u)=>{if(!Manager(u))return Denied();await using var c=new SqlConnection(db);await c.OpenAsync();var row=await Row(c,null,"SELECT TOP 1 Id,Name,ISNULL(TaxCode,N''),ISNULL(InvoiceName,N''),ISNULL(InvoiceEmail,N''),VatRate,ISNULL(Address,N'') FROM dbo.Stores WHERE IsActive=1 ORDER BY CreatedAt");return Results.Ok(row);});
        app.MapPut("/api/tax-settings",async(TaxSettingsInput x,ClaimsPrincipal u)=>{if(Role(u)!="owner")return Denied();if(x.VatRate<0||x.VatRate>100)return Results.BadRequest();await using var c=new SqlConnection(db);await c.OpenAsync();await Exec(c,null,"UPDATE dbo.Stores SET TaxCode=NULLIF(@tax,''),InvoiceName=NULLIF(@name,''),InvoiceEmail=NULLIF(@email,''),VatRate=@vat,Address=NULLIF(@address,'') WHERE Id=(SELECT TOP 1 Id FROM dbo.Stores WHERE IsActive=1 ORDER BY CreatedAt)",( "@tax",x.TaxCode?.Trim()??""),("@name",x.InvoiceName?.Trim()??""),("@email",x.InvoiceEmail?.Trim()??""),("@vat",x.VatRate),("@address",x.Address?.Trim()??""));return Results.Ok(x);});
        app.MapGet("/api/e-invoices",async(ClaimsPrincipal u)=>{if(!Cashier(u))return Denied();await using var c=new SqlConnection(db);await c.OpenAsync();return Results.Ok(await Rows(c,"SELECT TOP 100 i.Id,i.OrderId,o.OrderNumber,i.InvoiceNumber,i.BuyerName,i.BuyerTaxCode,i.Subtotal,i.TaxAmount,i.Total,i.Status,i.IssuedAt,i.CreatedAt FROM dbo.ElectronicInvoices i JOIN dbo.Orders o ON o.Id=i.OrderId ORDER BY i.CreatedAt DESC",r=>new{id=r.GetGuid(0),orderId=r.GetGuid(1),orderNumber=r.GetInt64(2),invoiceNumber=r.IsDBNull(3)?null:r.GetString(3),buyerName=r.IsDBNull(4)?null:r.GetString(4),buyerTaxCode=r.IsDBNull(5)?null:r.GetString(5),subtotal=r.GetInt32(6),taxAmount=r.GetInt32(7),total=r.GetInt32(8),status=r.GetString(9),issuedAt=r.IsDBNull(10)?(DateTime?)null:r.GetDateTime(10),createdAt=r.GetDateTime(11)}));});
        app.MapPost("/api/orders/{id:guid}/e-invoice",async(Guid id,InvoiceInput x,ClaimsPrincipal u)=>{if(!Cashier(u))return Denied();await using var c=new SqlConnection(db);await c.OpenAsync();var order=await Row(c,null,"SELECT o.Subtotal,(o.Discount+o.LoyaltyDiscount) TotalDiscount,s.VatRate FROM dbo.Orders o JOIN dbo.Stores s ON s.Id=o.StoreId WHERE o.Id=@id AND o.Status='paid'",("@id",id));if(order is null)return Results.NotFound(new{error="Chỉ lập hóa đơn cho đơn đã thanh toán."});var taxable=Convert.ToInt32(order["Subtotal"])-Convert.ToInt32(order["TotalDiscount"]);var tax=(int)Math.Round(taxable*Convert.ToDecimal(order["VatRate"])/100);await using var q=new SqlCommand("INSERT dbo.ElectronicInvoices(OrderId,BuyerName,BuyerTaxCode,BuyerEmail,Subtotal,TaxAmount,Total,Status,IssuedAt)OUTPUT INSERTED.Id VALUES(@o,@n,NULLIF(@tax,''),NULLIF(@email,''),@sub,@vat,@total,'issued',SYSUTCDATETIME())",c);q.Parameters.AddWithValue("@o",id);q.Parameters.AddWithValue("@n",x.BuyerName?.Trim()??"Khách lẻ");q.Parameters.AddWithValue("@tax",x.BuyerTaxCode?.Trim()??"");q.Parameters.AddWithValue("@email",x.BuyerEmail?.Trim()??"");q.Parameters.AddWithValue("@sub",taxable);q.Parameters.AddWithValue("@vat",tax);q.Parameters.AddWithValue("@total",taxable+tax);try{return Results.Ok(new{id=(Guid)(await q.ExecuteScalarAsync())!,taxAmount=tax,total=taxable+tax});}catch(SqlException){return Results.Conflict(new{error="Đơn này đã có hóa đơn điện tử."});}});
        app.MapGet("/api/stores",async(ClaimsPrincipal u)=>{if(Role(u)!="owner")return Denied();await using var c=new SqlConnection(db);await c.OpenAsync();return Results.Ok(await Rows(c,"SELECT Id,ISNULL(Code,N''),Name,ISNULL(Address,N''),IsActive,CreatedAt FROM dbo.Stores ORDER BY CreatedAt",r=>new{id=r.GetGuid(0),code=r.GetString(1),name=r.GetString(2),address=r.GetString(3),isActive=r.GetBoolean(4),createdAt=r.GetDateTime(5)}));});
        app.MapPost("/api/stores",async(StoreInput x,ClaimsPrincipal u)=>{if(Role(u)!="owner")return Denied();if(string.IsNullOrWhiteSpace(x.Name))return Results.BadRequest();await using var c=new SqlConnection(db);await c.OpenAsync();var id=Guid.NewGuid();await Exec(c,null,"INSERT dbo.Stores(Id,Code,Name,Address,Timezone)VALUES(@id,NULLIF(@code,''),@n,NULLIF(@a,''),'Asia/Ho_Chi_Minh');INSERT dbo.Areas(StoreId,Name,Position)VALUES(@id,N'Khu vực chính',1)",( "@id",id),("@code",x.Code?.Trim()??""),("@n",x.Name.Trim()),("@a",x.Address?.Trim()??""));return Results.Ok(new{id});});
        app.MapPut("/api/stores/{id:guid}",async(Guid id,StoreInput x,ClaimsPrincipal u)=>{if(Role(u)!="owner")return Denied();if(string.IsNullOrWhiteSpace(x.Name))return Results.BadRequest(new{error="Tên chi nhánh không được trống."});await using var c=new SqlConnection(db);await c.OpenAsync();return await Exec(c,null,"UPDATE dbo.Stores SET Code=NULLIF(@code,''),Name=@n,Address=NULLIF(@a,'') WHERE Id=@id",("@id",id),("@code",x.Code?.Trim()??""),("@n",x.Name.Trim()),("@a",x.Address?.Trim()??""))>0?Results.Ok(new{id}):Results.NotFound();});
        app.MapPatch("/api/stores/{id:guid}/status",async(Guid id,ActiveInput x,ClaimsPrincipal u)=>{if(Role(u)!="owner")return Denied();await using var c=new SqlConnection(db);await c.OpenAsync();if(!x.IsActive&&Convert.ToInt32(await Scalar(c,null,"SELECT COUNT(*) FROM dbo.Stores WHERE IsActive=1 AND Id<>@id",("@id",id)))==0)return Results.Conflict(new{error="Hệ thống phải còn ít nhất một chi nhánh hoạt động."});await Exec(c,null,"UPDATE dbo.Stores SET IsActive=@a WHERE Id=@id",("@a",x.IsActive),("@id",id));return Results.Ok(new{id,isActive=x.IsActive});});
        app.MapGet("/api/stores/report",async(DateTime? from,DateTime? to,ClaimsPrincipal u)=>{if(Role(u)!="owner")return Denied();var f=from??DateTime.UtcNow.Date.AddDays(-30);var t=to??DateTime.UtcNow.AddDays(1);await using var c=new SqlConnection(db);await c.OpenAsync();return Results.Ok(await Rows(c,"SELECT s.Id,s.Name,COUNT(DISTINCT CASE WHEN o.Status='paid' THEN o.Id END),ISNULL(SUM(CASE WHEN o.Status='paid' THEN o.Total ELSE 0 END),0) FROM dbo.Stores s LEFT JOIN dbo.Orders o ON o.StoreId=s.Id AND o.OpenedAt>=@f AND o.OpenedAt<@t GROUP BY s.Id,s.Name ORDER BY s.Name",r=>new{id=r.GetGuid(0),store=r.GetString(1),orders=r.GetInt32(2),revenue=r.GetInt32(3)},("@f",f),("@t",t)));});
    }

    static readonly PermissionDefinition[] Permissions={new("orders.create","Tạo và thêm món"),new("orders.cancel","Hủy món/đơn"),new("orders.pay","Thanh toán"),new("orders.refund","Hoàn tiền"),new("discount.apply","Áp dụng giảm giá"),new("menu.manage","Quản lý menu"),new("inventory.manage","Quản lý kho"),new("reports.view","Xem báo cáo"),new("staff.manage","Quản lý nhân sự")};
    static async Task ClosePaidOrder(SqlConnection c,SqlTransaction tx,Guid id,Guid user){await Exec(c,tx,"DECLARE @table uniqueidentifier=(SELECT TableId FROM dbo.Orders WHERE Id=@id),@customer uniqueidentifier=(SELECT CustomerId FROM dbo.Orders WHERE Id=@id),@amount int=(SELECT Total FROM dbo.Orders WHERE Id=@id);DECLARE @shift uniqueidentifier=(SELECT TOP 1 Id FROM dbo.WorkShifts WHERE OpenedBy=@u AND Status='open' ORDER BY OpenedAt DESC);UPDATE dbo.Orders SET Status='paid',ClosedAt=SYSUTCDATETIME(),ClosedBy=@u,ShiftId=@shift WHERE Id=@id;UPDATE dbo.OrderItems SET Status='paid' WHERE OrderId=@id AND Status<>'cancelled';UPDATE dbo.DiningTables SET Status=CASE WHEN EXISTS(SELECT 1 FROM dbo.Orders WHERE TableId=@table AND Status NOT IN ('paid','cancelled') AND Id<>@id) THEN 'occupied' ELSE 'available' END WHERE Id=@table;INSERT dbo.PromotionUsages(PromotionId,OrderId,CustomerId) SELECT PromotionId,Id,CustomerId FROM dbo.Orders WHERE Id=@id AND PromotionId IS NOT NULL AND NOT EXISTS(SELECT 1 FROM dbo.PromotionUsages WHERE OrderId=@id);IF @customer IS NOT NULL BEGIN UPDATE dbo.Customers SET TotalSpent=TotalSpent+@amount,Points=Points+(@amount/10000) WHERE Id=@customer;INSERT dbo.CustomerPointTransactions(CustomerId,OrderId,Points,Reason)VALUES(@customer,@id,@amount/10000,N'Tích điểm từ thanh toán') END",("@id",id),("@u",user));}
    static async Task Recalculate(SqlConnection c,SqlTransaction tx,Guid id)=>await Exec(c,tx,"UPDATE o SET Subtotal=x.Total,Total=x.Total FROM dbo.Orders o CROSS APPLY(SELECT ISNULL(SUM((i.UnitPrice+ISNULL(t.TopPrice,0))*i.Quantity),0) Total FROM dbo.OrderItems i OUTER APPLY(SELECT SUM(Price*Quantity) TopPrice FROM dbo.OrderItemToppings WHERE OrderItemId=i.Id)t WHERE i.OrderId=o.Id AND i.Status<>'cancelled')x WHERE o.Id=@id",("@id",id));
    static async Task<object?> Scalar(SqlConnection c,SqlTransaction? tx,string sql,params(string,object?)[] args){await using var q=new SqlCommand(sql,c,tx);foreach(var a in args)q.Parameters.AddWithValue(a.Item1,a.Item2??DBNull.Value);return await q.ExecuteScalarAsync();}
    static async Task<int> Exec(SqlConnection c,SqlTransaction? tx,string sql,params(string,object?)[] args){await using var q=new SqlCommand(sql,c,tx);foreach(var a in args)q.Parameters.AddWithValue(a.Item1,a.Item2??DBNull.Value);return await q.ExecuteNonQueryAsync();}
    static async Task<Dictionary<string,object?>?> Row(SqlConnection c,SqlTransaction? tx,string sql,params(string,object?)[] args){await using var q=new SqlCommand(sql,c,tx);foreach(var a in args)q.Parameters.AddWithValue(a.Item1,a.Item2??DBNull.Value);await using var r=await q.ExecuteReaderAsync();if(!await r.ReadAsync())return null;var d=new Dictionary<string,object?>(StringComparer.OrdinalIgnoreCase);for(var i=0;i<r.FieldCount;i++)d[r.GetName(i)]=r.IsDBNull(i)?null:r.GetValue(i);return d;}
    static async Task<List<object>> Rows(SqlConnection c,string sql,Func<SqlDataReader,object> map,params(string,object?)[] args){await using var q=new SqlCommand(sql,c);foreach(var a in args)q.Parameters.AddWithValue(a.Item1,a.Item2??DBNull.Value);await using var r=await q.ExecuteReaderAsync();var list=new List<object>();while(await r.ReadAsync())list.Add(map(r));return list;}
}

